create table agency_post_results(id text primary key,tenant_id text not null,package_id text not null,session_id text not null,ordinal int not null,previous_id text,kind text not null check(kind in ('award','failed','terminated')),report_id text,source_fingerprint text,snapshot_json jsonb not null,frozen_hash text not null,created_by text not null,created_at timestamptz not null default now(),unique(tenant_id,id),unique(tenant_id,package_id,ordinal),foreign key(tenant_id,session_id) references agency_assessment_sessions(tenant_id,id));
create table agency_post_documents(id text primary key,tenant_id text not null,package_id text not null,result_id text not null,kind text not null check(kind in ('announcement','notice','contract')),snapshot_json jsonb not null,frozen_hash text not null,file_version_id text not null,file_hash text not null,status text not null default 'generated' check(status in ('generated','reviewing','approved','rejected','published','issued','delivered','signed')),version bigint not null default 1,workflow_id text,created_by text not null,created_at timestamptz not null default now(),unique(tenant_id,id),foreign key(tenant_id,result_id) references agency_post_results(tenant_id,id),foreign key(tenant_id,file_version_id) references agency_file_versions(tenant_id,id));
create table agency_post_events(id text primary key,tenant_id text not null,package_id text not null,object_id text not null,kind text not null,snapshot_json jsonb not null,frozen_hash text not null,created_by text not null,created_at timestamptz not null default now(),unique(tenant_id,id));
create index agency_post_events_object on agency_post_events(tenant_id,object_id,created_at);
create table agency_post_issues(id text primary key,tenant_id text not null,package_id text not null,version bigint not null default 1,status text not null default 'open' check(status in ('open','handling','closed')),snapshot_json jsonb not null,created_by text not null,created_at timestamptz not null default now(),unique(tenant_id,id));
